#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=7

# Run from the repository root, whatever the caller's directory.
cd "$(dirname "${BASH_SOURCE[0]}")/.."

API="http://localhost:8000"
LLM_MODEL="qwen2.5:7b"
SAMPLE_PDF="samples/pdfs/bge-m3.pdf"
QUESTION="Which three retrieval functionalities does M3-Embedding support?"

# Release version, from the backend package metadata.
EXPECTED_VERSION=$(sed -n 's/^version = "\(.*\)"$/\1/p' backend/pyproject.toml | head -n1)

# json_eval EXPR: evaluate a Python expression over the JSON on stdin (bound to d).
json_eval() { python -X utf8 -c "import json,sys; d=json.load(sys.stdin); print($1)"; }

banner "Research Assistant: Docker release check"

# ── 1. WSL2 ─────────────────────────────────────────────────────────────────
stage "Enable WSL2 (needs admin, then a restart)"
if wsl.exe --status >/dev/null 2>&1; then
  say "✓ WSL is installed (wsl --status succeeded)."
else
  step "Press Start, type PowerShell, right-click it and choose 'Run as administrator'."
  step "Run:  wsl --install --no-distribution"
  note "(Docker Desktop brings its own Linux distribution, so none is needed.)"
  step "When it finishes, restart Windows."
  warn "After the restart, run this wizard again: it will pass this stage."
  pause "Press Enter to exit now (restart, then re-run), or Ctrl-C."
  exit 0
fi
pause

# ── 2. Docker Desktop ───────────────────────────────────────────────────────
stage "Start Docker Desktop on the WSL 2 engine"
step "Install Docker Desktop if needed: https://www.docker.com/products/docker-desktop/"
note "Images, models and volumes need about 10 GB of disk."
step "Start Docker Desktop from the Start menu and accept its terms if asked."
step "Settings → General: 'Use the WSL 2 based engine' must be ticked."
step "Wait until the whale icon says 'Docker Desktop is running'."
pause "Press Enter once Docker Desktop is running."
until docker info >/dev/null 2>&1; do
  warn "docker info failed: Docker is not ready yet."
  pause "Press Enter to check again (Ctrl-C to stop)."
done
say "Docker is running. $(docker compose version)"
note "Needs Compose v2.24 or newer (for the optional .env file)."
pause

# ── 3. Ollama ───────────────────────────────────────────────────────────────
stage "Ollama on the host with $LLM_MODEL"
if ! command -v ollama >/dev/null 2>&1; then
  warn "ollama is not on PATH. Install it from https://ollama.com/download,"
  warn "then open a new terminal and re-run this wizard."
  exit 1
fi
until ollama list >/dev/null 2>&1; do
  step "Start Ollama from the Start menu (it runs in the tray)."
  pause "Press Enter to check again."
done
if ollama list | grep -q "^${LLM_MODEL}"; then
  say "$LLM_MODEL is installed."
else
  say "Pulling $LLM_MODEL (4.7 GB)..."
  ollama pull "$LLM_MODEL"
fi
if grep -qE '^APP_VERSION=' .env 2>/dev/null; then
  warn ".env sets APP_VERSION, which overrides the release version ($EXPECTED_VERSION)."
  step "Delete the APP_VERSION line from .env before continuing."
  pause "Press Enter once it is removed."
fi
pause

# ── 4. Clean start ──────────────────────────────────────────────────────────
stage "Build and start the stack from a clean state"
if netstat -ano 2>/dev/null | grep -qE '127\.0\.0\.1:8000 .*LISTENING|0\.0\.0\.0:8000 .*LISTENING'; then
  warn "Something already listens on port 8000 (often a forgotten local uvicorn)."
  step "Stop it first (close that terminal, or end the python.exe in Task Manager)."
  pause "Press Enter once port 8000 is free."
fi
say "A clean start removes this stack's database and model-cache volumes."
note "Your local development database (port 5432/5433) and ./storage are not touched."
if confirm "Run 'docker compose down -v' for a clean start?"; then
  docker compose down -v
else
  note "Keeping existing volumes: this is then not a clean-start check."
fi
say "Building images and starting (first build takes several minutes)..."
docker compose up --build -d
say "Waiting for $API/health ..."
for _ in $(seq 1 120); do
  if curl -fsS "$API/health" >/dev/null 2>&1; then break; fi
  sleep 5
done
HEALTH=$(curl -fsS "$API/health") || { warn "Backend did not become healthy. See: docker compose logs backend"; exit 1; }
say "Health: $HEALTH"
VERSION=$(printf '%s' "$HEALTH" | json_eval 'd.get("version")')
[[ "$VERSION" == "$EXPECTED_VERSION" ]] || warn "Expected version $EXPECTED_VERSION, got $VERSION (check APP_VERSION in .env)."
MODELS=$(curl -fsS "$API/api/v1/models/health" || true)
say "LLM providers: $MODELS"
pause

# ── 5. First upload (downloads the embedding model) ─────────────────────────
stage "Upload a sample paper"
if [[ ! -f "$SAMPLE_PDF" ]]; then
  say "Downloading the sample papers..."
  python samples/download_samples.py
fi
COLLECTION_ID=$(curl -fsS -X POST "$API/api/v1/collections" \
  -H "Content-Type: application/json" \
  -d '{"name": "Release check"}' | json_eval 'd["id"]')
say "Created collection 'Release check' ($COLLECTION_ID)."
say "Uploading $SAMPLE_PDF. The first upload downloads bge-m3 (~2.3 GB),"
say "so expect several minutes. Follow along: docker compose logs -f backend"
UPLOAD=$(curl -fsS --max-time 3600 -F "file=@$SAMPLE_PDF" \
  -F "collection_ids=$COLLECTION_ID" "$API/api/v1/documents") \
  || { warn "Upload failed. See: docker compose logs backend"; exit 1; }
STATUS=$(printf '%s' "$UPLOAD" | json_eval 'd.get("processing_status")')
say "Document status: $STATUS"
[[ "$STATUS" == "completed" ]] || { warn "Expected 'completed'."; exit 1; }
pause

# ── 6. Cited answer via the API ─────────────────────────────────────────────
stage "Ask a question through the API"
say "Q: $QUESTION"
BODY=$(python -X utf8 -c 'import json,sys; print(json.dumps({"question": sys.argv[1], "collection_ids": [sys.argv[2]], "model_provider": "ollama", "model_name": sys.argv[3]}))' \
  "$QUESTION" "$COLLECTION_ID" "$LLM_MODEL")
ANSWER=$(curl -fsS --max-time 900 -X POST "$API/api/v1/chat" \
  -H "Content-Type: application/json" -d "$BODY") \
  || { warn "Chat request failed. Is Ollama reachable from Docker? See: docker compose logs backend"; exit 1; }
printf '%s' "$ANSWER" | python -X utf8 -c '
import json, sys
d = json.load(sys.stdin)
print("  A: " + d["answer"] + "\n")
for s in d["sources"]:
    if s["cited"]:
        print("  [%d] %s, PDF p. %d" % (s["citation_number"], s["document_title"], s["pdf_page_numbers"][0] + 1))
print("  insufficient_evidence: %s" % d["insufficient_evidence"])
'
CITED=$(printf '%s' "$ANSWER" | json_eval 'sum(1 for s in d["sources"] if s["cited"])')
if [[ "$CITED" -gt 0 ]]; then
  say "✓ The answer cites $CITED source(s)."
else
  warn "The answer has no citations. Ask again in the UI; if it repeats, note it."
fi
pause

# ── 7. Browser check ────────────────────────────────────────────────────────
stage "Check the web interface"
open_url "http://localhost:3000/chat"
step "Start a new chat, select the 'Release check' collection."
step "Ask: $QUESTION"
step "Click a citation such as [1]: the PDF should open at the cited page with"
step "the passage highlighted in the page text."
if confirm "Did the answer show citations and the PDF open at the right page?"; then
  say "✓ Release check passed. Tell Claude: 'Docker release check passed'."
else
  SKIPPED+=("Browser check failed: describe what you saw to Claude")
fi
note "The stack keeps running; stop it with: docker compose down"
pause

finish
}

run_wizard "$@"; exit
